import csv

def calculate_average(csv_file, column_name):
    values = []

    with open(csv_file, 'r') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            if not any(key == column_name for key in row):
                break
            value = float(row[column_name])
            values.append(value)

    return sum(values)/len(values)

