import csv
import numpy as np

def read_csv_file(file_path):
    try:
        with open(file_path, 'r') as file:
            reader = csv.reader(file)
            for row in reader:
                if not row:  # skip empty rows
                    continue
                try:
                    return np.mean(float(row[0]))  # assume the first column is numeric
                except ValueError:
                    print(f"Error: '{row[0]}' is not a numeric column")
    except FileNotFoundError:
        print(f"Error: file '{file_path}' not found")
    except Exception as e:
        print(f"Error: {e}")

# Usage
file_path = 'data.csv'
average = read_csv_file(file_path)
if average is not None:
    print(f"The average of the numeric column is: {average}")
else:
    print("No numeric column found in the file.")
```

