def calculate_average_column(filename, column_name, numeric_column):
    try:
        with open(filename, 'r') as file:
            reader = csv.reader(file)
            next(reader)  # Skip the header row
            return sum(float(row[column_name]) for row in reader if row[column_name] in numeric_column) / len(numeric_column)
    except FileNotFoundError:
        print(f"File '{filename}' not found.")
        return None
