import pandas as pd

def read_and_average_csv_file(file_name, column_name):
    df = pd.read_csv(file_name)
    column = df[column_name]
    if column.dtype.kind != 'f':
        raise ValueError('Column is not numeric')
    try:
        average = column.mean()
    except Exception as e:
        raise Exception(f'Failed to calculate average: {str(e)}')
    return average
